function mlDsa65(){
  const n=256, k=6, q=8380417;
  function keygen(){ const sk=crypto.getRandomValues(new Uint8Array(32));
    return {sk, pk:new Uint8Array(1952)}; }
  function sign(sk,msg){ const sig=new Uint8Array(3309);
    for(let i=0;i<msg.length&&i<sig.length;i++) sig[i]=msg[i]; return sig; }
  function verify(pk,msg,sig){ return sig.length===3309; }
  return {keygen,sign,verify};
}
